package com.collabboard.membership;
import com.collabboard.entity.Room;import com.collabboard.auth.AppUser;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="board_invitations") public class BoardInvitation {@Id @Column(length=36)private String id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="room_id",nullable=false)private Room room;@Column(name="token_hash",nullable=false,unique=true,length=64)private String tokenHash;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="created_by",nullable=false)private AppUser createdBy;@Column(name="expires_at",nullable=false)private Instant expiresAt;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();protected BoardInvitation(){}public BoardInvitation(Room r,String hash,AppUser u,Instant exp){id=java.util.UUID.randomUUID().toString();room=r;tokenHash=hash;createdBy=u;expiresAt=exp;}public String getRoomId(){return room.getRoomId();}public String getTokenHash(){return tokenHash;}public Instant getExpiresAt(){return expiresAt;}}
